INSERT INTO "niveles_ocupacionales" ("codigo", "etiqueta", "nombre", "descripcion", "orden", "id") VALUES
  ($o$0$o$, $o$0 Dirección y gerencia$o$, $o$Dirección y Gerencia$o$, NULL, $o$1$o$, $o$5c99dc83-b9a0-492a-bd51-ae6816fe78d2$o$),
  ($o$A$o$, $o$Nivel 1 (A)$o$, $o$Profesional$o$, $o$Las funciones de estas ocupaciones suelen ser muy variadas y complejas, su desempeño exige un alto grado de autonomía, responsabilidad por el trabajo de otros y ocasionalmente por la asignación de recursos.$o$, $o$2$o$, $o$b40514e8-f959-4c5a-9130-6c3cea2ad7e8$o$),
  ($o$B$o$, $o$Nivel 2 (B)$o$, $o$Técnicos Profesionales y Tecnólogos$o$, $o$Las funciones de las ocupaciones de este nivel son por lo general muy variadas, demandan responsabilidad de supervisión, un apreciable grado de autonomía y juicio evaluativo.$o$, $o$3$o$, $o$ae836606-f89a-4ac6-8b52-9dfcbad37cb8$o$),
  ($o$C$o$, $o$Nivel 3,4 (C)$o$, $o$Oficios Calificados$o$, $o$Las funciones de estas ocupaciones combinan actividades físicas e intelectuales, en algunos casos variadas y complejas, con algún nivel de autonomía para su desempeño.$o$, $o$4$o$, $o$a13ab620-afe9-4689-b65e-d42409a2873a$o$),
  ($o$D$o$, $o$Nivel 6 (D)$o$, $o$Oficios Elementales$o$, $o$Las funciones de estas ocupaciones son sencillas y repetitivas y se desempeñan en actividades fundamentalmente de carácter físico, con alto nivel de subordinación.$o$, $o$5$o$, $o$95cdd41a-ad76-4023-b0ca-32268fc9567e$o$);
