-- Cuántas cuentas hay antes de tocar nada (se comprueba al final).
CREATE TEMP TABLE cuentas_antes ON COMMIT DROP AS SELECT count(*)::bigint AS n FROM public.usuarios;

-- Vaciar las tablas que trae este archivo. Sin CASCADE a propósito: si otra tabla las
-- referencia y no está en la lista, falla en vez de arrastrarla.
TRUNCATE public."archivos", public."cargas_datos", public."cargas_datos_ocupacionales", public."centros_formacion", public."ciiu_clases", public."ciiu_secciones", public."configuracion", public."cortes_ocupacionales", public."criterios_ocupacionales", public."departamentos", public."departamentos_alias", public."empresas", public."indicadores_ocupacionales", public."municipios", public."niveles_cualificacion", public."niveles_formacion", public."niveles_ocupacionales", public."ocupaciones", public."periodos", public."programas_formacion", public."programas_sobresalientes", public."proyectos_inversion", public."proyectos_inversion_ubicaciones";

-- Las llaves foráneas se comprueban al final (las páginas y sus versiones se citan entre sí).
SET session_replication_role = replica;

